import{_ as r,c as t,o,a5 as a}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"共享包与横切关注点","description":"","frontmatter":{"title":"共享包与横切关注点","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#8","branch":"main","level":0,"order":8,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/08-shared-packages-and-cross-cutting-concerns/index.md","filePath":"posts/projects/zfeed/08-shared-packages-and-cross-cutting-concerns/index.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/08-shared-packages-and-cross-cutting-concerns/index.md"};function i(g,e,l,p,n,d){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="共享包与横切关注点" tabindex="-1">共享包与横切关注点 <a class="header-anchor" href="#共享包与横切关注点" aria-label="Permalink to &quot;共享包与横切关注点&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/front.go" target="_blank" rel="noreferrer">app/front/front.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/config/config.go" target="_blank" rel="noreferrer">app/front/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/userloginstatusauthmiddleware.go" target="_blank" rel="noreferrer">app/front/internal/middleware/userloginstatusauthmiddleware.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/logoutlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/logoutlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go" target="_blank" rel="noreferrer">pkg/errorx/error.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors_test.go" target="_blank" rel="noreferrer">pkg/grpcx/interceptors_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/hotrank/formula_bench_test.go" target="_blank" rel="noreferrer">pkg/hotrank/formula_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go</a></li></ul></details><p><code>zfeed</code> 代码库依赖位于 <code>pkg/</code> 和 <code>orm/</code> 的一组共享包，以保证各微服务之间的一致性。这些包负责标准化 gRPC 通信、错误转换、环境管理，以及手机号归一化、热度排行公式等与具体领域弱相关的通用工具。</p><h3 id="共享包的架构角色" tabindex="-1">共享包的架构角色 <a class="header-anchor" href="#共享包的架构角色" aria-label="Permalink to &quot;共享包的架构角色&quot;">​</a></h3><p>共享包提供了让独立服务能够稳定通信、行为可预测的“胶水层”。通过集中处理拦截器、日志和错误映射逻辑，系统得以维持统一的可观测性与可靠性轮廓。</p><h4 id="代码实体与逻辑映射" tabindex="-1">代码实体与逻辑映射 <a class="header-anchor" href="#代码实体与逻辑映射" aria-label="Permalink to &quot;代码实体与逻辑映射&quot;">​</a></h4><p>下图展示 <code>pkg/</code> 目录中的具体代码实体如何管理系统中的请求和数据流。</p><p>共享逻辑流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go#L21-L22" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go#21-22</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go#L46-L53" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go#46-53</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go#L21-L25" target="_blank" rel="noreferrer">pkg/errorx/error.go#21-25</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go#L123-L148" target="_blank" rel="noreferrer">pkg/errorx/error.go#123-148</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go#L5-L15" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go#5-15</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/hotrank/formula_bench_test.go#L11-L12" target="_blank" rel="noreferrer">pkg/hotrank/formula_bench_test.go#11-12</a></p><hr><h3 id="grpc-拦截器与错误处理" tabindex="-1">gRPC 拦截器与错误处理 <a class="header-anchor" href="#grpc-拦截器与错误处理" aria-label="Permalink to &quot;gRPC 拦截器与错误处理&quot;">​</a></h3><p><code>grpcx</code> 包为服务端和客户端实现了一套稳健的中间件链。它处理分布式追踪所需的请求 ID 传播，使用 <code>logx</code> 进行结构化日志记录，并通过 panic 恢复避免服务崩溃。</p><p>其中的关键组件是 <code>ErrorUnaryServerInterceptor</code>，它负责衔接内部业务逻辑与 gRPC 协议。它会自动把 <code>errorx.BizError</code> 类型转换为标准化的 gRPC 状态码。在 <code>front-api</code> 侧，<code>errorx.ResponseFromError</code> 会完成最后一步映射，将错误转换为面向客户端的 HTTP 状态码。</p><p>详情请参见 <a href="./01-grpc-interceptors-and-error-handling.html">gRPC 拦截器与错误处理</a>。</p><p>拦截器与错误映射</p><table tabindex="0"><thead><tr><th>组件</th><th>函数/类型</th><th>职责</th></tr></thead><tbody><tr><td>服务端拦截器</td><td><code>RecoveryUnaryServerInterceptor</code></td><td>从 panic 中恢复并记录堆栈跟踪 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go#L164-L181" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go#164-181</a></td></tr><tr><td>服务端拦截器</td><td><code>ErrorUnaryServerInterceptor</code></td><td>将 <code>BizError</code> 转换为 gRPC status <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go#L147-L162" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go#147-162</a></td></tr><tr><td>客户端拦截器</td><td><code>RequestIDClientInterceptor</code></td><td>将 <code>x-request-id</code> 转发到下游 RPC <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go#L72-L84" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go#72-84</a></td></tr><tr><td>错误系统</td><td><code>BizError</code></td><td>具备 HTTP/gRPC 状态码感知能力的自定义错误类型 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go#L21-L25" target="_blank" rel="noreferrer">pkg/errorx/error.go#21-25</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go#L1-L181" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go#1-181</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go#L1-L212" target="_blank" rel="noreferrer">pkg/errorx/error.go#1-212</a></p><hr><h3 id="orm、环境与工具" tabindex="-1">ORM、环境与工具 <a class="header-anchor" href="#orm、环境与工具" aria-label="Permalink to &quot;ORM、环境与工具&quot;">​</a></h3><p>系统的基础设施交互通过 <code>orm</code> 和 <code>envx</code> 包进行标准化。这些包确保数据库连接使用一致的设置初始化，例如慢查询日志，同时保证环境变量能在本地、Docker 或 CI 等不同执行上下文中正确加载。</p><p><code>pkg/</code> 目录还包含一些专用逻辑：</p><ul><li><code>mobilex</code>：提供 <code>Normalize</code> 和 <code>IsValid</code> 函数，用来处理多种国际和中国大陆手机号格式 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go#L5-L20" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go#5-20</a></li><li><code>hotrank</code>：实现基于时间衰减的评分算法，由 <code>content-rpc</code> 用于生成推荐 Feed <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/hotrank/formula_bench_test.go#L11-L19" target="_blank" rel="noreferrer">pkg/hotrank/formula_bench_test.go#11-19</a></li><li><code>xxljob</code>：分布式任务调度集成。</li></ul><p>详情请参见 <a href="./02-orm-environment-loading-and-utility-packages.html">ORM、环境加载与工具包</a>。</p><p>工具实体关系</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/front.go#L27-L27" target="_blank" rel="noreferrer">app/front/front.go#27</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go#L22-L41" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go#22-41</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/hotrank/formula_bench_test.go#L17-L17" target="_blank" rel="noreferrer">pkg/hotrank/formula_bench_test.go#17</a></p><hr><h3 id="共享包汇总" tabindex="-1">共享包汇总 <a class="header-anchor" href="#共享包汇总" aria-label="Permalink to &quot;共享包汇总&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>关键路径</th><th>主要用途</th></tr></thead><tbody><tr><td><code>grpcx</code></td><td><code>pkg/grpcx/</code></td><td>标准化 gRPC 拦截器和日志上下文 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go</a></td></tr><tr><td><code>errorx</code></td><td><code>pkg/errorx/</code></td><td>统一错误类型，以及 HTTP/gRPC 状态映射 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go" target="_blank" rel="noreferrer">pkg/errorx/error.go</a></td></tr><tr><td><code>envx</code></td><td><code>pkg/envx/</code></td><td>环境变量加载和 DSN 构造 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/front.go#L27-L27" target="_blank" rel="noreferrer">app/front/front.go#27</a></td></tr><tr><td><code>mobilex</code></td><td><code>pkg/mobilex/</code></td><td>手机号校验与归一化 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go</a></td></tr><tr><td><code>hotrank</code></td><td><code>pkg/hotrank/</code></td><td>面向内容排行的时间衰减评分公式 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/hotrank/formula_bench_test.go" target="_blank" rel="noreferrer">pkg/hotrank/formula_bench_test.go</a></td></tr><tr><td><code>utils</code></td><td><code>pkg/utils/</code></td><td>通用辅助函数，例如上下文解析 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go#L33-L33" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go#33</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/grpcx/interceptors.go#L1-L30" target="_blank" rel="noreferrer">pkg/grpcx/interceptors.go#1-30</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go#L1-L25" target="_blank" rel="noreferrer">pkg/errorx/error.go#1-25</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/mobilex/mobile.go#L1-L20" target="_blank" rel="noreferrer">pkg/mobilex/mobile.go#1-20</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go#L15-L16" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go#15-16</a></p>',29)])])}const f=r(c,[["render",i]]);export{h as __pageData,f as default};
